local hash={}local band,bor,bxor,bnot=bit32.band,bit32.bor,bit32.bxor,bit32.bnot local rshift,rrotate=bit32.rshift,bit32.rrotate local MOD=4294967296 local K={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2,}local HEX={}for i=0,255 do HEX[i]=("%02x"):format(i)end local function u32(x)return x%MOD end local function add4(a,b,c,d)return(a+b+c+d)%MOD end local function add5(a,b,c,d,e)return(a+b+c+d+e)%MOD end local function be32(n)return string.char(math.floor(n/16777216)%256,math.floor(n/65536)%256,math.floor(n/256)%256,n%256)end local function hex32(n)return HEX[math.floor(n/16777216)%256]..HEX[math.floor(n/65536)%256]..HEX[math.floor(n/256)%256]..HEX[n%256]end function hash.sha256(data)if type(data)~="string"then return nil end local h0,h1,h2,h3=0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a local h4,h5,h6,h7=0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19 local bits=#data*8 local pad=(56-(#data+1)%64)%64 local msg=data.."\128"..string.rep("\0",pad)..be32(math.floor(bits/MOD))..be32(bits%MOD)local w={}for i=1,#msg,64 do for j=1,16 do local a,b,c,d=msg:byte(i+(j-1)*4,i+(j-1)*4+3)w[j]=((a*256+b)*256+c)*256+d end for j=17,64 do local x,y=w[j-15],w[j-2]local s0=bxor(rrotate(x,7),rrotate(x,18),rshift(x,3))local s1=bxor(rrotate(y,17),rrotate(y,19),rshift(y,10))w[j]=add4(w[j-16],s0,w[j-7],s1)end local a,b,c,d=h0,h1,h2,h3 local e,f,g,h=h